<?php $this->assign('title', 'Agenda'); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3">Agenda</h1><p class="text-body-secondary">Consultas e status de atendimento.</p></div><?= $this->Html->link('Agendar consulta', ['action' => 'add'], ['class' => 'btn btn-primary']) ?></div><div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Início</th><th>Paciente</th><th>Profissional</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($consultas as $consulta): ?><tr><td><?= h($consulta->inicio->format('d/m/Y H:i')) ?></td><td><?= h($consulta->paciente->nome_social ?: $consulta->paciente->nome_completo) ?></td><td><?= h($consulta->profissional->nome) ?></td><td><span class="badge text-bg-secondary"><?= h($consulta->status) ?></span></td><td><?php if ($consulta->status === 'agendada'): ?><?= $this->Form->postLink('Confirmar', ['action' => 'status', $consulta->id], ['data' => ['status' => 'confirmada'], 'class' => 'btn btn-sm btn-outline-success']) ?> <?= $this->Form->postLink('Cancelar', ['action' => 'status', $consulta->id], ['data' => ['status' => 'cancelada', 'motivo' => 'Cancelamento operacional'], 'class' => 'btn btn-sm btn-outline-danger']) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
